-- Generated by supabase/schemas/diff.sh from the schema files. Read it
-- before pushing: renames come out as drop + create, which loses data.

SET local check_function_bodies = off;

DROP FUNCTION "core"."create_employee"(text, integer, integer, text, date);

CREATE OR REPLACE FUNCTION core.create_employee (
  p_name      text,
  p_color     bigint,
  p_salary    integer,
  p_notes     text,
  p_joined_on date
)
  RETURNS core.employees
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  new_employee core.employees;
begin
  insert into core.employees (name, color, salary, notes)
  values (p_name, p_color, p_salary, p_notes)
  returning * into new_employee;

  insert into core.employee_events (employee_id, event_type, event_date, created_by)
  values (new_employee.id, 'joined', p_joined_on, auth.uid());

  return new_employee;
end;
$function$;

REVOKE ALL ON FUNCTION "core"."create_employee"(text, bigint, integer, text, date) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "core"."create_employee"(text, bigint, integer, text, date) TO "authenticated";

